def eq(t):return '<div class="fcfe-equation" data-tex="'+html.escape(t,quote=True)+'"></div>'
def slide(n,t,b,x=''):return f'<section class="slide" id="fcf-{n}" {x}><div class="slide-header"><div class="eyebrow">LECTURE 08 · {n:02} / 12</div><h2>{t}</h2></div>{b}</section>'
def grid(a,b):return '<div class="fcf-grid"><div class="card">'+a+'</div><div class="card">'+b+'</div></div>'
def reveal(i,b):return f'<button class="btn btn-accent" data-reveal="{i}">Reveal & discuss</button><div id="{i}" hidden>{b}</div>'
img=base64.b64encode((r/'support/previews/dcf2-slide10-image5.png').read_bytes()).decode()
